<?php require_once __DIR__.'/../includes/auth.php';$pageTitle='Products';$base='/shop-inventory-management';$q=trim($_GET['q']??'');$cat=filter_input(INPUT_GET,'category',FILTER_VALIDATE_INT)?:0;$status=$_GET['status']??'';$page=max(1,(int)($_GET['page']??1));$limit=10;$where=[];$args=[];if($q!==''){$where[]='(p.name LIKE ? OR p.sku LIKE ?)';$args[]='%'.$q.'%';$args[]='%'.$q.'%';}if($cat){$where[]='p.category_id=?';$args[]=$cat;}if($status==='low')$where[]='p.quantity<=p.minimum_stock';elseif($status==='out')$where[]='p.quantity=0';elseif($status==='in')$where[]='p.quantity>0';$w=$where?' WHERE '.implode(' AND ',$where):'';$st=$pdo->prepare('SELECT COUNT(*) FROM products p'.$w);$st->execute($args);$total=(int)$st->fetchColumn();$pages=max(1,(int)ceil($total/$limit));$offset=($page-1)*$limit;$st=$pdo->prepare('SELECT p.*,c.name category_name,s.name supplier_name FROM products p JOIN categories c ON c.id=p.category_id LEFT JOIN suppliers s ON s.id=p.supplier_id'.$w.' ORDER BY p.id DESC LIMIT '.$limit.' OFFSET '.$offset);$st->execute($args);$rows=$st->fetchAll();$categories=$pdo->query('SELECT id,name FROM categories ORDER BY name')->fetchAll();require __DIR__.'/../includes/header.php';require __DIR__.'/../includes/sidebar.php';?>
<div class="page-heading"><div><h1>Products</h1><p>Manage your product catalogue, prices and stock.</p></div><a class="btn primary" href="create.php">＋ Add product</a></div><div class="panel"><form class="toolbar" method="get"><input name="q" placeholder="Search product name or SKU…" value="<?=e($q)?>"><select name="category"><option value="0">All categories</option><?php foreach($categories as $c):?><option value="<?=$c['id']?>" <?=$cat===$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select><select name="status"><option value="">All stock</option><option value="low" <?=$status==='low'?'selected':''?>>Low stock</option><option value="out" <?=$status==='out'?'selected':''?>>Out of stock</option><option value="in" <?=$status==='in'?'selected':''?>>In stock</option></select><button class="btn">Filter</button><a class="btn" href="index.php">Reset</a></form><div class="table-wrap"><table><thead><tr><th>Product</th><th>SKU</th><th>Category</th><th>Supplier</th><th>Purchase</th><th>Selling</th><th>Stock</th><th>Actions</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="8" class="empty">No products match these filters.</td></tr><?php else:foreach($rows as $r):?><tr><td><strong><?=e($r['name'])?></strong></td><td><code><?=e($r['sku'])?></code></td><td><?=e($r['category_name'])?></td><td><?=e($r['supplier_name']??'—')?></td><td><?=money($r['purchase_price'])?></td><td><?=money($r['selling_price'])?></td><td><span class="badge <?=$r['quantity']==0?'danger':($r['quantity']<=$r['minimum_stock']?'warning':'success')?>"><?=$r['quantity']?> units</span></td><td class="actions"><a class="btn small" href="view.php?id=<?=$r['id']?>">View</a><a class="btn small" href="edit.php?id=<?=$r['id']?>">Edit</a><form method="post" action="delete.php" class="inline-form" data-confirm="Delete this product? Products with sales history cannot be deleted."><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn small danger">Delete</button></form></td></tr><?php endforeach;endif;?></tbody></table></div><div class="pagination"><span>Showing <?=min($total,$offset+1)?>–<?=min($total,$offset+count($rows))?> of <?=$total?></span><div><?php if($page>1):?><a class="btn small" href="?<?=e(http_build_query(array_merge($_GET,['page'=>$page-1])))?>">← Previous</a><?php endif;?> <span class="page-number">Page <?=$page?> / <?=$pages?></span> <?php if($page<$pages):?><a class="btn small" href="?<?=e(http_build_query(array_merge($_GET,['page'=>$page+1])))?>">Next →</a><?php endif;?></div></div></div><?php require __DIR__.'/../includes/footer.php';?>
